    /* sdd-asis-lifecycle:begin defaultCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    isOk = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isOk"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isOk")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isOk"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("isOk")))));
    if (isOk !== '') {
        if (isOk) {
            await $c.win.alert('제출되었습니다');
        } else {
            await $c.win.alert('제출시 오류가 발생했습니다.');
        }
        await $c.win.alert('화면 이동 미완 — 목적지 미확인(as-is: /listInvstg/listFee.do?method=getFeeList&bzCd=5&pageIndex=). 전환 대상 화면이 확정되면 연결됩니다.') + null;
    }
    /* sdd-asis-lifecycle:end */
};


